def solve(g):
    n,m=len(g),len(g[0])
    for P in range(1,m+1):
        res={}
        ok=True
        for r in range(n):
            for c in range(m):
                if g[r][c]:
                    d=(c-r)%P
                    if d in res and res[d]!=g[r][c]: ok=False;break
                    res[d]=g[r][c]
            if not ok: break
        if ok and len(res)==P:
            return [[res[(c-r)%P] for c in range(m)] for r in range(n)]
    return None
